/**
 * Google's redirect lands here. This path IS the canonical redirect URI.
 *
 * ---------------------------------------------------------------------------
 * 🚨 THE PATH IS NOT INCIDENTAL
 *
 * `/api/account/mail/callback` is generated by `googleConsoleSetup()` on the
 * Brain and entered into the Google Cloud console from that output. Renaming
 * this directory breaks every existing user's sign-in with
 * `redirect_uri_mismatch`, and the first person to notice would be a user.
 *
 * ---------------------------------------------------------------------------
 * 🚨 THIS ROUTE DECIDES NOTHING
 *
 * It reads three query parameters, attaches the session's identity, and asks
 * the Brain. It does not validate the state, does not check expiry, does not
 * look at the code. Every one of those checks exists on the Brain, and a
 * consumer that pre-judged them would become a second, weaker copy of the
 * logic that stops a mailbox being grafted onto the wrong account.
 *
 * ---------------------------------------------------------------------------
 * 🚨 NOTHING FROM GOOGLE REACHES A REDIRECT
 *
 * The destination comes from the Brain's answer, which is a same-site path the
 * Brain validated when the attempt was minted. The `state`, the `code` and
 * Google's `error` are never placed in a URL, a log line or a response body:
 * one of them is a bearer credential, and a redirect target is the easiest
 * place in a web application to leak one through a Referer header.
 */

import { callBrain } from '@/server/brain/gateway'
import { absoluteHttpUrl, readEnv } from '@/server/auth/env'
import { resolveRequestPrincipal } from '@/server/tenancy/requestPrincipal'
import { canConnectMail } from '@/server/mail/mailPrincipal'

export const dynamic = 'force-dynamic'

/**
 * `Response.redirect` requires an absolute URL, so an empty or relative
 * `APP_BASE_URL` would produce a 500 on a consent that otherwise succeeded.
 * The request origin is the last resort rather than the first choice: behind
 * the proxy it is the internal address, which is a bad redirect but still
 * better than failing a completed authorization.
 */
const appBase = (request: Request): string =>
  absoluteHttpUrl(readEnv('APP_BASE_URL')) ?? new URL(request.url).origin

/**
 * Land the browser somewhere in this app.
 *
 * The path is re-checked here even though the Brain already validated it. It
 * crossed a process boundary in between, and this is the last place before it
 * becomes a Location header — the cost of checking twice is nothing, and the
 * cost of being wrong is sending someone who just authorised mailbox access to
 * a site of an attacker's choosing.
 */
function land(request: Request, path: string, query: string): Response {
  const safe = path.startsWith('/') && !path.startsWith('//') ? path : '/'
  let resolved: URL
  try {
    resolved = new URL(safe, appBase(request))
    if (resolved.origin !== new URL(appBase(request)).origin) resolved = new URL('/', appBase(request))
  } catch {
    resolved = new URL('/', appBase(request))
  }
  resolved.search = query
  return Response.redirect(resolved.toString(), 302)
}

export async function GET(request: Request): Promise<Response> {
  const resolved = await resolveRequestPrincipal()
  if (!resolved || !canConnectMail(resolved.principal)) {
    /*
     * Their session ended while they were on Google's consent screen. The
     * attempt is dead either way, and the honest landing is the app with a
     * sign-in prompt — not an API error page for a browser navigation.
     */
    return land(request, '/', 'mail=signin')
  }

  const params = new URL(request.url).searchParams
  const result = await callBrain(
    {
      kind: 'completeMailConnection',
      ...(params.get('state') ? { state: params.get('state')! } : {}),
      ...(params.get('code') ? { code: params.get('code')! } : {}),
      ...(params.get('error') ? { error: params.get('error')! } : {}),
    },
    { principal: resolved.principal },
  )

  if (result.kind === 'ok') {
    const value = result.value as { returnTo?: string }
    return land(request, typeof value.returnTo === 'string' ? value.returnTo : '/', 'mail=connected')
  }

  /*
   * A refused callback is a 400 from the Brain, which arrives here as
   * `brain_error`. It is NOT rendered as an error page: this is a browser
   * navigation at the end of a flow the user started, and the right ending is
   * the app with a message — never a JSON body, and never Google's own words.
   */
  return land(request, '/', 'mail=failed')
}
